class RenderedStatusBar {
    constructor(fragment, a) {
        this.a = a;
        fragment.appendChild(this.a.hoverElement);
    }
    get hoverElement() {
        return this.a.hoverElement;
    }
    get actions() {
        return this.a.actions;
    }
    dispose() {
        this.a.dispose();
    }
}
